// Initialize SearchManager on top of Infinispan cache instance
SearchManager searchManager = Search.getSearchManager(cache);
searchManager.getStatistics().setStatisticsEnabled(true);

// Create entity-bound QueryBuilder
QueryBuilder builder = searchManager.buildQueryBuilderForClass(PatientRecord.class).get();

// Assemble boolean junction clauses
BooleanJunction<BooleanJunction> booleanQuery = builder.bool();

// Add fuzzy keyword match
booleanQuery.should(
    builder.keyword()
           .fuzzy()
           .withEditDistanceUpTo(2)
           .onField("patientName")
           .matching(searchTerm)
           .createQuery()
);

// Add exact match filter
booleanQuery.must(
    builder.keyword()
           .onField("status")
           .matching("ACTIVE")
           .createQuery()
);

Query query = booleanQuery.createQuery();

public <T> List<T> searchWithPagination(
    Query query,
    Class<T> entityClass,
    String sortField,
    int page,
    int size
) {
    CacheQuery<T> cacheQuery = searchManager.getQuery(query, IndexedQueryMode.FETCH, entityClass);

    Sort sort = new Sort(new SortField(sortField, SortField.Type.STRING, false));

    return cacheQuery
        .sort(sort)
        .firstResult(page * size)
        .maxResults(size)
        .list();
}
